def connectTwoGroups(cost: list[list[int]]) -> int:
    sz1, sz2 = len(cost), len(cost[0])
    min_col_cost = [min(cost[i][j] for i in range(sz1)) for j in range(sz2)]
    memo = {}
    def dfs(i, mask):
        if (i, mask) in memo: return memo[(i, mask)]
        if i == sz1:
            # Connect any remaining unconnected nodes in group 2 to their cheapest group 1 node
            ans = sum(min_col_cost[j] for j in range(sz2) if not (mask & (1 << j)))
            return ans
        res = float('inf')
        for j in range(sz2):
            res = min(res, cost[i][j] + dfs(i + 1, mask | (1 << j)))
        memo[(i, mask)] = res
        return res
    return dfs(0, 0)

